// Generated release data. Canonical SQL belongs to the closed version sources.
export const MATERIAL_CLOSURE_RELEASE = Object.freeze({"version":"identity-guarantees-v1","checksum":"751dfd673947b6a9cb172cda98c6313605937c01200d2831971eab7884f2e752","manifestSha256":"4b91693bccee7a3d93d338a3bc18f31741a2f358e9691f77e5a640df6e0d29f5","sql":"-- Core schema version identity-guarantees-v1 (closed build artifact).\n\nSET ROLE backbone_gov;\n\n-- gov/identity_task_exists.sql\n\n-- Private native refusal classification; never an alternate payload read API.\nCREATE FUNCTION gov.identity_task_exists(p_id uuid) RETURNS boolean\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\nDECLARE old_person text:=coalesce(current_setting('backbone.principal',true),''); old_run text:=coalesce(current_setting('backbone.run',true),''); old_secret text:=coalesce(current_setting('backbone.secret',true),''); value boolean;\nBEGIN\n  PERFORM set_config('backbone.run','',true); PERFORM set_config('backbone.secret','',true); PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n  SELECT EXISTS(SELECT FROM app.tasks WHERE workspace_id=sec.current_workspace() AND id=p_id) INTO value;\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RETURN value;\nEXCEPTION WHEN OTHERS THEN\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true); RAISE;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_task_exists(uuid) FROM PUBLIC,backbone_app,backbone_operator;\n\n-- gov/identity_effect_owner.sql\n\n-- Private native refusal classification; never an alternate payload read API.\nCREATE FUNCTION gov.identity_effect_owner(p_id uuid) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\nDECLARE old_person text:=coalesce(current_setting('backbone.principal',true),''); old_run text:=coalesce(current_setting('backbone.run',true),''); old_secret text:=coalesce(current_setting('backbone.secret',true),''); value jsonb;\nBEGIN\n  PERFORM set_config('backbone.run','',true); PERFORM set_config('backbone.secret','',true); PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n  SELECT (SELECT jsonb_build_object('person',on_behalf_of_id) FROM app.effects WHERE workspace_id=sec.current_workspace() AND id=p_id) INTO value;\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RETURN value;\nEXCEPTION WHEN OTHERS THEN\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true); RAISE;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_effect_owner(uuid) FROM PUBLIC,backbone_app,backbone_operator;\n\n-- gov/queue_run.sql\n\n-- Queue a run of an agent on a task under a mandate it holds. The person the mandate serves queues\n-- it, and must be able to see the task. A run starts with what its task's conversation carries.\n-- It takes its mandate's carrier here, for good (sec.t_run_piece); p_piece, when given, must be the\n-- mandate's piece.\nCREATE OR REPLACE FUNCTION gov.queue_run(p_task uuid, p_agent uuid, p_mandate uuid, p_routine uuid DEFAULT NULL, p_piece uuid DEFAULT NULL) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  ws uuid := sec.current_workspace();\n  me uuid := sec.current_principal();\n  m record;\n  new_id uuid := gen_random_uuid();\nBEGIN\n  IF me IS NULL THEN\n    RAISE EXCEPTION 'no_identity: the session acts as nobody';\n  END IF;\n  IF sec.names_run() THEN\n    RAISE EXCEPTION 'not_by_runs: a run does not queue runs';\n  END IF;\n  IF NOT gov.identity_task_exists(p_task) THEN\n    RAISE EXCEPTION 'not_found: no such task in this workspace';\n  END IF;\n  IF NOT sec.task_visible(p_task) THEN\n    RAISE EXCEPTION 'denied: the task is not shared with this person';\n  END IF;\n  SELECT * INTO m FROM app.mandates WHERE workspace_id = ws AND id = p_mandate;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'not_found: no such mandate in this workspace';\n  END IF;\n  IF m.subject_id <> p_agent THEN\n    RAISE EXCEPTION 'mandate_holder: the run''s agent does not hold the mandate';\n  END IF;\n  IF me <> m.on_behalf_of_id AND me <> sec.system_principal() THEN\n    RAISE EXCEPTION 'role: a run is queued by the person its mandate serves';\n  END IF;\n  IF m.revoked_at IS NOT NULL OR m.expires_at <= clock_timestamp() THEN\n    RAISE EXCEPTION 'revoked: the mandate no longer stands';\n  END IF;\n  INSERT INTO app.runs (workspace_id, id, task_id, agent_id, mandate_id, routine_id, piece_id) VALUES (ws, new_id, p_task, p_agent, p_mandate, p_routine, p_piece);\n  INSERT INTO ops.run_queue (run_id, workspace_id, carrier_key, claimable_after)\n  SELECT new_id, ws, x.carrier_key, clock_timestamp() FROM app.runs x WHERE x.workspace_id = ws AND x.id = new_id;\n  PERFORM gov._initial_marks(new_id);\n  PERFORM gov._append('run.queued', new_id::text, jsonb_build_object('task', p_task, 'agent', p_agent, 'mandate', p_mandate,\n    'carrier', (SELECT carrier_key FROM app.runs WHERE workspace_id = ws AND runs.id = new_id)));\n  RETURN new_id;\nEND\n$$;\n\n-- gov/propose_undo.sql\n\n-- A person reverses a completed effect through the gateway: the person it was for, or an owner or\n-- admin who sees it; never a run or an agent. Only a succeeded effect whose operation has a way\n-- back is undoable, and one undo stands at a time. The undo is the person's own act: within their\n-- role it is allowed, above it it goes to another owner or admin (effect-gateway contract, undo).\nCREATE OR REPLACE FUNCTION gov.propose_undo(p_effect uuid, p_args jsonb, p_description text, p_expected_version text, p_idempotency_key text)\nRETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  ws uuid := sec.current_workspace();\n  me uuid := sec.current_principal();\n  e record;\n  beneficiary jsonb;\n  existing record;\n  cls record;\n  undo_op text;\n  new_id uuid := gen_random_uuid();\n  hash text;\n  role_ceiling smallint;\n  status text;\n  route text;\n  reason text;\nBEGIN\n  IF me IS NULL THEN\n    RAISE EXCEPTION 'no_identity: the session acts as nobody';\n  END IF;\n  PERFORM gov._lock_workspace();\n  me:=sec.current_principal();\n  IF me IS NULL THEN RAISE EXCEPTION 'no_identity: the session acts as nobody'; END IF;\n  IF sec.names_run() OR sec.principal_kind(me) <> 'person' THEN\n    RAISE EXCEPTION 'role: an undo is asked for by a person';\n  END IF;\n  beneficiary:=gov.identity_effect_owner(p_effect);\n  IF beneficiary IS NULL THEN RAISE EXCEPTION 'not_found: no such effect in this workspace'; END IF;\n  IF me IS DISTINCT FROM (beneficiary->>'person')::uuid AND NOT sec.is_admin(me) THEN\n    RAISE EXCEPTION 'someone_else: an undo is for the person the effect was for, or an admin who sees it';\n  END IF;\n  SELECT * INTO e FROM app.effects x WHERE x.workspace_id = ws AND x.id = p_effect;\n  IF NOT FOUND THEN RAISE EXCEPTION 'someone_else: an undo is for the person the effect was for, or an admin who sees it'; END IF;\n  IF me <> e.on_behalf_of_id AND NOT (sec.is_admin(me) AND sec.effect_visible(p_effect)) THEN\n    RAISE EXCEPTION 'someone_else: an undo is for the person the effect was for, or an admin who sees it';\n  END IF;\n  hash := sec.args_hash(coalesce(p_args, '{}'));\n  SELECT * INTO existing FROM app.effects x WHERE x.workspace_id = ws AND x.idempotency_key = p_idempotency_key;\n  IF FOUND THEN\n    IF existing.undo_of IS NOT DISTINCT FROM p_effect AND existing.args_hash = hash THEN\n      RETURN existing.id;\n    END IF;\n    RAISE EXCEPTION 'reused_key: the idempotency key names another change';\n  END IF;\n  SELECT x.undo INTO undo_op FROM gov._operation_class(e.operation, NULL, NULL, NULL) x;\n  IF e.status <> 'succeeded' OR undo_op IS NULL OR e.undo_of IS NOT NULL THEN\n    RAISE EXCEPTION 'not_undoable: only a completed effect with a way back is undone';\n  END IF;\n  IF EXISTS (SELECT FROM app.effects x WHERE x.workspace_id = ws AND x.undo_of = p_effect AND x.status NOT IN ('cancelled', 'denied', 'failed')) THEN\n    RAISE EXCEPTION 'conflict: an undo of this effect already stands';\n  END IF;\n  SELECT * INTO cls FROM gov._operation_class(undo_op, NULL, NULL, NULL);\n  role_ceiling := CASE WHEN sec.is_admin(me) THEN 4 ELSE 3 END;\n  IF cls.effect_class > role_ceiling THEN\n    status := 'awaiting_checker';\n    route := 'needs_checker';\n    reason := 'above_role';\n  ELSE\n    status := 'allowed';\n    route := CASE WHEN cls.effect_class = 1 THEN 'free' ELSE 'allowed' END;\n  END IF;\n  INSERT INTO app.effects (workspace_id, id, run_id, task_id, proposer_id, on_behalf_of_id, mandate_id, tool, operation, connection,\n                           effect_class, external_party, args, args_hash, description, expected_version, idempotency_key,\n                           status, route, route_reason, undo_of)\n  VALUES (ws, new_id, NULL, e.task_id, me, e.on_behalf_of_id, NULL, 'undo', undo_op, e.connection, cls.effect_class, cls.external,\n          coalesce(p_args, '{}'), hash, coalesce(p_description, ''), p_expected_version, p_idempotency_key, status, route, reason, p_effect);\n  PERFORM gov._append('effect.proposed', new_id::text, gov._effect_payload(new_id) || jsonb_build_object(\n    'route', route, 'reason', reason, 'description', sec.digest(p_description)));\n  IF status = 'awaiting_checker' THEN\n    UPDATE app.effects SET decision_id = gov._open_decision('effect', new_id, me, e.on_behalf_of_id, reason, hash,\n      gov._effect_question(new_id), false, 'person', NULL) WHERE workspace_id = ws AND id = new_id;\n  ELSE\n    PERFORM gov._enqueue_effect(new_id);\n  END IF;\n  RETURN new_id;\nEND\n$$;\n\n-- gov/propose_candidate.sql\n\n-- The principal acting now proposes a statement for accepted knowledge, with verbatim evidence from\n-- recorded sources. It names no terms of its own: those are set when promotion is requested. What\n-- the proposing run had read, and what its evidence is, come with the candidate.\nCREATE OR REPLACE FUNCTION gov.propose_candidate(p_statement text, p_evidence jsonb, p_proposed_by uuid, p_topic text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  old_person text:=coalesce(current_setting('backbone.principal',true),''); old_run text:=coalesce(current_setting('backbone.run',true),''); old_secret text:=coalesce(current_setting('backbone.secret',true),'');\n  ws uuid := sec.current_workspace();\n  me uuid := sec.current_principal();\n  run uuid := sec.current_run();\n  run_untrusted boolean := false;\n  run_sensitive boolean := false;\n  new_id uuid := gen_random_uuid();\n  untrusted boolean;\nBEGIN\n  IF me IS NULL THEN\n    RAISE EXCEPTION 'no_identity: the session acts as nobody';\n  END IF;\n  IF p_proposed_by IS DISTINCT FROM me THEN\n    RAISE EXCEPTION 'denied: a candidate is proposed by the principal acting now';\n  END IF;\n  IF p_statement IS NULL OR length(p_statement) NOT BETWEEN 1 AND 4000 OR jsonb_typeof(p_evidence) IS DISTINCT FROM 'array'\n     OR jsonb_array_length(p_evidence) = 0 THEN\n    RAISE EXCEPTION 'invalid: a candidate states something and cites its evidence';\n  END IF;\n  PERFORM set_config('backbone.run','',true); PERFORM set_config('backbone.secret','',true); PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n  IF EXISTS (SELECT FROM jsonb_array_elements(p_evidence) x\n             WHERE NOT EXISTS (SELECT FROM app.episodes e WHERE e.workspace_id = ws AND e.id::text = x ->> 'episode')) THEN\n    RAISE EXCEPTION 'not_found: the evidence cites a source that was not recorded';\n  END IF;\n  SELECT bool_or(e.trust = 'untrusted') INTO untrusted FROM jsonb_array_elements(p_evidence) x\n  JOIN app.episodes e ON e.workspace_id = ws AND e.id::text = x ->> 'episode';\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  IF run IS NOT NULL THEN\n    SELECT x.tainted_untrusted, x.tainted_sensitive INTO run_untrusted, run_sensitive FROM app.runs x WHERE x.workspace_id = ws AND x.id = run;\n  END IF;\n  INSERT INTO app.knowledge_candidates (workspace_id, id, statement, topic, evidence, proposed_by, run_id, on_behalf_of,\n                                        words_untrusted, kept)\n  VALUES (ws, new_id, p_statement, coalesce(p_topic, 'general'), p_evidence, me, run, sec.acting_for(),\n          coalesce(untrusted, false) OR run_untrusted,\n          run_untrusted AND run_sensitive);\n  PERFORM gov._append('knowledge.proposed', new_id::text, jsonb_build_object('run', run, 'topic', sec.digest(p_topic)));\n  RETURN new_id;\nEXCEPTION WHEN OTHERS THEN\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RAISE;\nEND\n$$;\n\n-- gov/_promotion_sources_allowed.sql\n\n-- Source eligibility is independent of the checker's project audience. Only a\n-- boolean leaves this bounded private observation; kept payloads remain private.\nCREATE OR REPLACE FUNCTION gov._promotion_sources_allowed(p_candidate uuid) RETURNS boolean\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\nDECLARE old_person text:=coalesce(current_setting('backbone.principal',true),''); old_run text:=coalesce(current_setting('backbone.run',true),''); old_secret text:=coalesce(current_setting('backbone.secret',true),''); allowed boolean;\nBEGIN\n  PERFORM set_config('backbone.run','',true); PERFORM set_config('backbone.secret','',true); PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n  SELECT EXISTS(SELECT FROM gov.eligible_knowledge_sources WHERE candidate_id=p_candidate) INTO allowed;\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RETURN allowed;\nEXCEPTION WHEN OTHERS THEN\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RAISE;\nEND\n$$;\n\n-- sec/t_candidate_input_capture_v1.sql\n\n-- Material closure hardening v1. Preserves the released proposal shapes; lineage stays conservative.\nCREATE OR REPLACE FUNCTION sec.t_candidate_input_capture_v1() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  old_person text:=coalesce(current_setting('backbone.principal',true),''); old_run text:=coalesce(current_setting('backbone.run',true),''); old_secret text:=coalesce(current_setting('backbone.secret',true),'');\n  ws uuid;\n  actor uuid;\n  native_run uuid;\n  beneficiary uuid;\n  r app.runs%ROWTYPE;\n  e app.episodes%ROWTYPE;\n  source_run_task uuid;\n  connection app.connections%ROWTYPE;\n  boundary app.ledger%ROWTYPE;\n  captured app.ledger%ROWTYPE;\n  head app.ledger_heads%ROWTYPE;\n  citation jsonb;\n  matches bigint;\n  cited_untrusted boolean := false;\n  manifest jsonb;\n  claim_digest text;\n  reserved boolean;\nBEGIN\n  IF TG_OP <> 'INSERT' OR TG_TABLE_SCHEMA <> 'app' OR TG_TABLE_NAME <> 'knowledge_candidates' THEN\n    RAISE EXCEPTION 'invalid: candidate input capture belongs only to candidate insertion';\n  END IF;\n  IF current_setting('transaction_isolation') <> 'read committed' THEN\n    RAISE EXCEPTION 'paused: candidate input capture requires READ COMMITTED isolation';\n  END IF;\n  -- No actor/run/source read before the waiting statement. All authority is rederived later.\n  PERFORM gov._lock_workspace();\n  ws := sec.current_workspace();\n  IF ws IS NULL OR NEW.workspace_id IS DISTINCT FROM ws THEN\n    RAISE EXCEPTION 'no_identity: candidate capture requires its native workspace';\n  END IF;\n  actor := sec.current_principal();\n  native_run := sec.current_run();\n  IF actor IS NULL OR (sec.names_run() AND native_run IS NULL)\n     OR NEW.proposed_by IS DISTINCT FROM actor OR NEW.run_id IS DISTINCT FROM native_run THEN\n    RAISE EXCEPTION 'stale: candidate identity no longer matches the authenticated native actor and run';\n  END IF;\n  IF NEW.id IS NULL OR EXISTS (SELECT FROM app.knowledge_candidates c WHERE c.workspace_id=ws AND c.id=NEW.id)\n     OR EXISTS (SELECT FROM app.knowledge_candidate_inputs p WHERE p.workspace_id=ws AND p.candidate_id=NEW.id)\n     OR EXISTS (SELECT FROM app.ledger l WHERE l.workspace_id=ws AND l.entry_type='knowledge.proposed' AND l.subject=NEW.id::text) THEN\n    RAISE EXCEPTION 'conflict: candidate capture requires a new candidate, proof and proposal identity';\n  END IF;\n  IF NEW.status IS DISTINCT FROM 'open' OR NEW.owner_id IS NOT NULL OR NEW.valid_from IS NOT NULL\n     OR NEW.valid_to IS NOT NULL OR NEW.terms_hash IS NOT NULL THEN\n    RAISE EXCEPTION 'invalid: candidate creation grants no acceptance or terms';\n  END IF;\n  IF NEW.statement IS NULL OR length(NEW.statement) NOT BETWEEN 1 AND 4000 OR NEW.topic IS NULL\n     OR NEW.created_at IS NULL OR jsonb_typeof(NEW.evidence) IS DISTINCT FROM 'array'\n     OR jsonb_array_length(NEW.evidence)=0 THEN\n    RAISE EXCEPTION 'invalid: a candidate states a claim and cites recorded sources';\n  END IF;\n  IF native_run IS NOT NULL THEN\n    BEGIN\n      -- Older native recorders may own run before head. Never wait in the reverse order.\n      SELECT x.* INTO r FROM app.runs x WHERE x.workspace_id=ws AND x.id=native_run FOR UPDATE NOWAIT;\n    EXCEPTION WHEN lock_not_available THEN\n      RAISE EXCEPTION 'paused: candidate run is changing; retry after its native owner settles';\n    END;\n    IF NOT FOUND THEN RAISE EXCEPTION 'stale: candidate run no longer exists'; END IF;\n    r := gov._holder(native_run,r.fence);\n    IF gov.run_standing(native_run) IS DISTINCT FROM 'ok' OR r.status IS DISTINCT FROM 'running'\n       OR r.agent_id IS DISTINCT FROM actor THEN\n      RAISE EXCEPTION 'stale: candidate run no longer has native standing';\n    END IF;\n    beneficiary := gov._run_person(native_run);\n    IF beneficiary IS NULL OR NOT EXISTS (SELECT FROM app.principals p WHERE p.workspace_id=ws\n         AND p.id=beneficiary AND p.kind='person' AND p.status='active')\n       OR NOT sec.task_visible_to(r.task_id,beneficiary) THEN\n      RAISE EXCEPTION 'denied: candidate run has no current authorised native beneficiary';\n    END IF;\n  ELSE\n    -- A standalone agent stays an agent; its owner is an audience, not a personal declaration.\n    beneficiary := sec.acting_for();\n    IF beneficiary IS NOT NULL AND NOT EXISTS (SELECT FROM app.principals p WHERE p.workspace_id=ws\n         AND p.id=beneficiary AND p.kind='person' AND p.status='active') THEN\n      RAISE EXCEPTION 'denied: candidate has no active native receiving person';\n    END IF;\n  END IF;\n  NEW.created_at := clock_timestamp();\n  NEW.proposed_by := actor;\n  NEW.run_id := native_run;\n  NEW.on_behalf_of := beneficiary;\n\n  SELECT count(*) INTO matches FROM app.ledger l WHERE l.workspace_id=ws\n    AND l.entry_type='knowledge.dependencies_enabled';\n  IF matches<>1 THEN RAISE EXCEPTION 'paused: candidate needs one native dependency boundary'; END IF;\n  SELECT l.* INTO boundary FROM app.ledger l WHERE l.workspace_id=ws\n    AND l.entry_type='knowledge.dependencies_enabled';\n  SELECT h.* INTO head FROM app.ledger_heads h WHERE h.workspace_id=ws;\n  SELECT l.* INTO captured FROM app.ledger l WHERE l.workspace_id=ws AND l.seq=head.last_seq;\n  IF NOT FOUND OR boundary.subject IS NOT NULL\n     OR boundary.payload IS DISTINCT FROM jsonb_build_object('version','material-closure-foundation-v1')\n     OR boundary.seq>captured.seq OR captured.seq>=9223372036854775807\n     OR head.last_hash IS DISTINCT FROM captured.hash\n     OR boundary.hash IS DISTINCT FROM sec.ledger_hash(boundary.prev_hash,boundary.workspace_id,boundary.seq,\n       boundary.entry_type,boundary.actor_id,boundary.subject,boundary.payload,boundary.at)\n     OR captured.hash IS DISTINCT FROM sec.ledger_hash(captured.prev_hash,captured.workspace_id,captured.seq,\n       captured.entry_type,captured.actor_id,captured.subject,captured.payload,captured.at) THEN\n    RAISE EXCEPTION 'paused: candidate boundary or captured native head is inconsistent';\n  END IF;\n\n  PERFORM set_config('backbone.run','',true); PERFORM set_config('backbone.secret','',true); PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n  FOR citation IN SELECT value FROM jsonb_array_elements(NEW.evidence) LOOP\n    -- Match the released source lookup exactly. Unsupported citation shapes are captured\n    -- as incomplete by the manifest; no promotion-time evidence rule is moved here.\n    SELECT x.* INTO e FROM app.episodes x WHERE x.workspace_id=ws AND x.id::text=citation ->> 'episode';\n    -- Proposal captures inputs; the released promotion crossing checks literal evidence.\n    -- A mismatch is retained in the immutable manifest and cannot certify personal lineage.\n    IF NOT FOUND OR e.content_hash IS DISTINCT FROM encode(sha256(convert_to(e.content,'UTF8')),'hex') THEN\n      RAISE EXCEPTION 'invalid: candidate source is missing or its recorded content hash is inconsistent';\n    END IF;\n    cited_untrusted := cited_untrusted OR e.trust='untrusted';\n    -- Never use System-recorder visibility or same-run identity as an audience exemption.\n    IF e.task_id IS NOT NULL AND NOT (\n         (beneficiary IS NOT NULL AND sec.task_visible_to(e.task_id,beneficiary))\n         OR (beneficiary IS NULL AND EXISTS (SELECT FROM app.tasks t WHERE t.workspace_id=ws\n           AND t.id=e.task_id AND t.visibility='workspace'))) THEN\n      RAISE EXCEPTION 'denied: candidate citation is outside its receiving audience';\n    END IF;\n    IF e.run_id IS NOT NULL THEN\n      SELECT x.task_id INTO source_run_task FROM app.runs x WHERE x.workspace_id=ws AND x.id=e.run_id;\n      IF NOT FOUND OR NOT ((beneficiary IS NOT NULL AND sec.task_visible_to(source_run_task,beneficiary))\n          OR (beneficiary IS NULL AND EXISTS (SELECT FROM app.tasks t WHERE t.workspace_id=ws\n            AND t.id=source_run_task AND t.visibility='workspace'))) THEN\n        RAISE EXCEPTION 'denied: candidate source run is outside its receiving audience';\n      END IF;\n    END IF;\n    IF e.connection_id IS NOT NULL THEN\n      SELECT x.* INTO connection FROM app.connections x WHERE x.workspace_id=ws AND x.id=e.connection_id;\n      IF NOT FOUND OR (connection.scope='person' AND connection.owner_id IS DISTINCT FROM beneficiary) THEN\n        RAISE EXCEPTION 'denied: candidate connected source belongs to another audience';\n      END IF;\n    END IF;\n    IF e.source_kind='message' AND e.source_ref ~ '^message:[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'\n       AND EXISTS (SELECT FROM app.messages m WHERE m.workspace_id=ws\n         AND m.id=substring(e.source_ref FROM 9)::uuid AND m.only_for IS NOT NULL\n         AND m.only_for IS DISTINCT FROM beneficiary) THEN\n      RAISE EXCEPTION 'denied: candidate message is kept for another person';\n    END IF;\n    reserved := e.source_kind='mcp' OR (e.source_kind='file' AND left(e.source_ref,9) COLLATE \"C\"='material:');\n    IF reserved AND gov._material_source_projection(e.id) IS DISTINCT FROM 'live' THEN\n      RAISE EXCEPTION 'paused: cited material is withdrawn or its native binding is unknown';\n    END IF;\n  END LOOP;\n  -- Preserve the released candidate semantics, now from post-lock native facts.\n  -- Incomplete lineage is represented independently; false taint is never a clean proof.\n  NEW.words_untrusted := cited_untrusted OR CASE WHEN native_run IS NULL THEN false ELSE r.tainted_untrusted END;\n  NEW.kept := CASE WHEN native_run IS NULL THEN false ELSE r.tainted_untrusted AND r.tainted_sensitive END;\n  claim_digest := gov._candidate_claim_digest_v1(NEW::app.knowledge_candidates);\n  IF claim_digest IS NULL OR claim_digest !~ '^[a-f0-9]{64}$' THEN\n    RAISE EXCEPTION 'paused: candidate claim digest is unavailable';\n  END IF;\n  manifest := gov._candidate_input_manifest_v1(NEW::app.knowledge_candidates,captured.seq);\n  IF EXISTS (SELECT FROM jsonb_array_elements(manifest -> 'unknown') u\n      WHERE u ->> 'kind' IN ('source_history_not_demonstrated','material_registration_history_not_demonstrated')\n        AND EXISTS (SELECT FROM jsonb_array_elements(NEW.evidence) c WHERE c ->> 'episode'=u ->> 'episode_id')\n        AND EXISTS (SELECT FROM app.episodes x WHERE x.workspace_id=ws AND x.id::text=u ->> 'episode_id'\n          AND (x.source_kind='mcp' OR (x.source_kind='file' AND left(x.source_ref,9) COLLATE \"C\"='material:')))) THEN\n    RAISE EXCEPTION 'paused: cited material has no unambiguous native read history';\n  END IF;\n  -- Always fresh INSERT, no conflict recovery, no reuse, no backfill. Same-statement\n  -- failure rolls back this proof; deferred candidate FK permits the BEFORE ordering.\n  INSERT INTO app.knowledge_candidate_inputs(workspace_id,candidate_id,format_version,\n    boundary_seq,boundary_hash,capture_seq,capture_hash,proposed_by,run_id,run_fence,run_task_id,\n    on_behalf_of,run_tainted_untrusted,run_tainted_sensitive,words_untrusted,kept,\n    claim_digest,input_manifest,input_sha256)\n  VALUES(ws,NEW.id,1,boundary.seq,boundary.hash,captured.seq,captured.hash,actor,native_run,\n    CASE WHEN native_run IS NULL THEN NULL ELSE r.fence END,\n    CASE WHEN native_run IS NULL THEN NULL ELSE r.task_id END,beneficiary,\n    CASE WHEN native_run IS NULL THEN NULL ELSE r.tainted_untrusted END,\n    CASE WHEN native_run IS NULL THEN NULL ELSE r.tainted_sensitive END,NEW.words_untrusted,NEW.kept,\n    claim_digest,manifest,encode(sha256(convert_to(manifest::text,'UTF8')),'hex'));\n  -- No _append here: the old body must append knowledge.proposed immediately at H+1.\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RAISE;\nEND\n$$;\nALTER FUNCTION sec.t_candidate_input_capture_v1() OWNER TO backbone_gov;\nREVOKE ALL ON FUNCTION sec.t_candidate_input_capture_v1() FROM PUBLIC, backbone_app, backbone_operator;\nGRANT EXECUTE ON FUNCTION sec.t_candidate_input_capture_v1() TO backbone_owner;\n\nSET ROLE backbone_owner;\n\n-- owner/identity_store_guarantees.sql\n\n-- Every identity store retains forced RLS and the exact native tenant/truncate guarantees.\nALTER TABLE app.identity_accounts ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_accounts FORCE ROW LEVEL SECURITY;\nDROP POLICY tenant_wall ON app.identity_accounts;\nCREATE POLICY tenant_wall ON app.identity_accounts AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=(SELECT sec.current_workspace())) WITH CHECK(workspace_id=(SELECT sec.current_workspace()));\nCREATE TRIGGER no_truncate BEFORE TRUNCATE ON app.identity_accounts FOR EACH STATEMENT EXECUTE FUNCTION sec.t_refuse_truncate();\nALTER TABLE app.identity_agents ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_agents FORCE ROW LEVEL SECURITY;\nDROP POLICY tenant_wall ON app.identity_agents;\nCREATE POLICY tenant_wall ON app.identity_agents AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=(SELECT sec.current_workspace())) WITH CHECK(workspace_id=(SELECT sec.current_workspace()));\nCREATE TRIGGER no_truncate BEFORE TRUNCATE ON app.identity_agents FOR EACH STATEMENT EXECUTE FUNCTION sec.t_refuse_truncate();\nALTER TABLE app.identity_invitations ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_invitations FORCE ROW LEVEL SECURITY;\nDROP POLICY tenant_wall ON app.identity_invitations;\nCREATE POLICY tenant_wall ON app.identity_invitations AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=(SELECT sec.current_workspace())) WITH CHECK(workspace_id=(SELECT sec.current_workspace()));\nCREATE TRIGGER no_truncate BEFORE TRUNCATE ON app.identity_invitations FOR EACH STATEMENT EXECUTE FUNCTION sec.t_refuse_truncate();\nALTER TABLE app.identity_sessions ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_sessions FORCE ROW LEVEL SECURITY;\nDROP POLICY tenant_wall ON app.identity_sessions;\nCREATE POLICY tenant_wall ON app.identity_sessions AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=(SELECT sec.current_workspace())) WITH CHECK(workspace_id=(SELECT sec.current_workspace()));\nCREATE TRIGGER no_truncate BEFORE TRUNCATE ON app.identity_sessions FOR EACH STATEMENT EXECUTE FUNCTION sec.t_refuse_truncate();\nALTER TABLE app.identity_projects ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_projects FORCE ROW LEVEL SECURITY;\nDROP POLICY tenant_wall ON app.identity_projects;\nCREATE POLICY tenant_wall ON app.identity_projects AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=(SELECT sec.current_workspace())) WITH CHECK(workspace_id=(SELECT sec.current_workspace()));\nCREATE TRIGGER no_truncate BEFORE TRUNCATE ON app.identity_projects FOR EACH STATEMENT EXECUTE FUNCTION sec.t_refuse_truncate();\nALTER TABLE app.identity_project_people ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_project_people FORCE ROW LEVEL SECURITY;\nDROP POLICY tenant_wall ON app.identity_project_people;\nCREATE POLICY tenant_wall ON app.identity_project_people AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=(SELECT sec.current_workspace())) WITH CHECK(workspace_id=(SELECT sec.current_workspace()));\nCREATE TRIGGER no_truncate BEFORE TRUNCATE ON app.identity_project_people FOR EACH STATEMENT EXECUTE FUNCTION sec.t_refuse_truncate();\nALTER TABLE app.identity_task_projects ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_task_projects FORCE ROW LEVEL SECURITY;\nDROP POLICY tenant_wall ON app.identity_task_projects;\nCREATE POLICY tenant_wall ON app.identity_task_projects AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=(SELECT sec.current_workspace())) WITH CHECK(workspace_id=(SELECT sec.current_workspace()));\nCREATE TRIGGER no_truncate BEFORE TRUNCATE ON app.identity_task_projects FOR EACH STATEMENT EXECUTE FUNCTION sec.t_refuse_truncate();\nALTER TABLE app.identity_directory ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_directory FORCE ROW LEVEL SECURITY;\nDROP POLICY tenant_wall ON app.identity_directory;\nCREATE POLICY tenant_wall ON app.identity_directory AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=(SELECT sec.current_workspace())) WITH CHECK(workspace_id=(SELECT sec.current_workspace()));\nCREATE TRIGGER no_truncate BEFORE TRUNCATE ON app.identity_directory FOR EACH STATEMENT EXECUTE FUNCTION sec.t_refuse_truncate();\nALTER TABLE app.identity_directory_deleted ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_directory_deleted FORCE ROW LEVEL SECURITY;\nDROP POLICY tenant_wall ON app.identity_directory_deleted;\nCREATE POLICY tenant_wall ON app.identity_directory_deleted AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=(SELECT sec.current_workspace())) WITH CHECK(workspace_id=(SELECT sec.current_workspace()));\nCREATE TRIGGER no_truncate BEFORE TRUNCATE ON app.identity_directory_deleted FOR EACH STATEMENT EXECUTE FUNCTION sec.t_refuse_truncate();\nALTER TABLE app.identity_workspace_projects ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_workspace_projects FORCE ROW LEVEL SECURITY;\nDROP POLICY tenant_wall ON app.identity_workspace_projects;\nCREATE POLICY tenant_wall ON app.identity_workspace_projects AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=(SELECT sec.current_workspace())) WITH CHECK(workspace_id=(SELECT sec.current_workspace()));\nCREATE TRIGGER no_truncate BEFORE TRUNCATE ON app.identity_workspace_projects FOR EACH STATEMENT EXECUTE FUNCTION sec.t_refuse_truncate();\n\nRESET ROLE;\n"} as const);
